.btn {
  font: 600 13px/1 Inter, 'Pretendard', sans-serif;
  border-radius: var(--radius-md);
  padding: 0 14px;
  height: 32px;
  display: inline-flex; align-items: center; gap: 6px;
  border: 0;
  transition: background 100ms ease;
}
.btn-primary { background: var(--color-primary-500); color: #1A0E08; }
.btn-primary:hover { background: var(--color-primary-600); }
.btn-primary:active { background: var(--color-primary-700); }
.btn-primary:disabled { background: var(--color-neutral-100); color: var(--text-disabled); }
.btn-secondary { background: var(--bg-elevated); color: var(--text-primary); border: 1px solid var(--border-strong); }
.btn-secondary:hover { background: var(--bg-subtle); }
.btn-ghost { background: transparent; color: var(--color-primary-500); }
.btn-danger { background: var(--color-error-fg); color: #1A0606; }
.input {
  background: var(--bg-subtle);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-sm);
  padding: 6px 10px;
  font-size: 13px;
  font-family: ui-monospace, monospace;
}
.input:focus { outline: none; border-color: var(--border-focus); box-shadow: 0 0 0 2px rgba(255,108,55,0.30); }
.card { background: var(--bg-elevated); border: 1px solid var(--border-default); border-radius: var(--radius-lg); padding: 16px; }
.card-elevated { box-shadow: var(--shadow-md); border-color: transparent; }
.card-outlined { box-shadow: none; }
.method { padding: 2px 8px; border-radius: var(--radius-sm); font-size: 11px; font-weight: 700; line-height: 16px; color: #0E1A0F; font-family: ui-monospace, monospace; display: inline-flex; align-items: center; }
.method-get    { background: var(--method-get); }
.method-post   { background: var(--method-post); }
.method-put    { background: var(--method-put); }
.method-delete { background: var(--method-delete); }
.method-patch  { background: var(--method-patch); }

.tag { padding: 0 8px; height: 20px; border-radius: var(--radius-sm); font-size: 11px; font-weight: 600; line-height: 20px; }
.tag-solid   { background: var(--color-primary-500); color: #1A0E08; }
.tag-subtle  { background: var(--color-primary-50); color: var(--color-primary-800); }
.tag-outline { border: 1px solid var(--border-default); color: var(--text-primary); }
.topnav { height: 44px; background: var(--color-neutral-0); color: var(--text-primary); display: flex; align-items: center; padding: 0 16px; gap: 12px; }
.sidebar { width: 280px; background: var(--bg-subtle); border-right: 1px solid var(--border-default); padding: 12px 8px; height: 100vh; }
